package fleetflow;
import java.util.*;
public class Module4 {
 public static void menu(Scanner sc){while(true){System.out.println("\n--- MODULE 4: NETWORK FLOW ---\n1. Edmonds-Karp max-flow + min-cut demo\n2. Bipartite matching demo\n0. Back");int c=Util.readInt(sc,"Choice: ");if(c==0)return;if(c==1){int n=Util.readInt(sc,"Number of vertices (2..20): ");if(n<2||n>20)continue;int[][]cap=new int[n][n];int m=Util.readInt(sc,"Number of directed edges: ");for(int i=0;i<m;i++){int u=Util.readInt(sc,"From (0-based): "),v=Util.readInt(sc,"To (0-based): "),w=Util.readInt(sc,"Capacity: ");if(u>=0&&u<n&&v>=0&&v<n&&w>=0)cap[u][v]=w;}int s=Util.readInt(sc,"Source vertex: "),t=Util.readInt(sc,"Sink vertex: ");if(s>=0&&s<n&&t>=0&&t<n&&s!=t)System.out.println("Maximum flow = "+maxFlow(cap,s,t));}else if(c==2){int l=Util.readInt(sc,"Left vertices: "),r=Util.readInt(sc,"Right vertices: ");List<List<Integer>>g=new ArrayList<>();for(int i=0;i<l;i++){g.add(new ArrayList<>());System.out.println("Right neighbors for left vertex "+i+" (space-separated indexes): ");String line=Util.readLine(sc,"> ");for(String x:line.trim().split("\\s+"))try{int v=Integer.parseInt(x);if(v>=0&&v<r)g.get(i).add(v);}catch(Exception ignored){}}System.out.println("Maximum matching size = "+matching(g,r));}else System.out.println("Invalid choice.");}}
 public static int maxFlow(int[][]capacity,int s,int t){int n=capacity.length,flow=0;int[][]r=new int[n][n];for(int i=0;i<n;i++)r[i]=capacity[i].clone();int[]parent=new int[n];while(true){Arrays.fill(parent,-1);parent[s]=s;Queue<Integer>q=new ArrayDeque<>();q.add(s);while(!q.isEmpty()&&parent[t]==-1){int u=q.remove();for(int v=0;v<n;v++)if(parent[v]==-1&&r[u][v]>0){parent[v]=u;q.add(v);}}if(parent[t]==-1)break;int aug=Integer.MAX_VALUE;for(int v=t;v!=s;v=parent[v])aug=Math.min(aug,r[parent[v]][v]);for(int v=t;v!=s;v=parent[v]){r[parent[v]][v]-=aug;r[v][parent[v]]+=aug;}flow+=aug;}return flow;}
 private static boolean dfs(int u,List<List<Integer>>g,boolean[]seen,int[]match){for(int v:g.get(u))if(!seen[v]){seen[v]=true;if(match[v]<0||dfs(match[v],g,seen,match)){match[v]=u;return true;}}return false;}
 public static int matching(List<List<Integer>>g,int right){int[]match=new int[right];Arrays.fill(match,-1);int n=0;for(int u=0;u<g.size();u++)if(dfs(u,g,new boolean[right],match))n++;return n;}
}
